export type Post = {
  slug: string;
  title: string;
  excerpt: string;
  category: string;
  /** ISO date, used for <time> and sorting. */
  date: string;
  readingMinutes: number;
  /** Cover art, 16:10. Generated by make-post-covers.py from the brand palette. */
  image: string;
  /** Paragraphs. Keep them short. */
  body: string[];
};

