export function getPost(slug: string) {
  return posts.find((p) => p.slug === slug);
}

export const formatPostDate = (iso: string) =>
  new Date(iso).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
